CREATE TABLE APP.AGENCE (
  ID NUMBER NOT NULL,
  NOM VARCHAR2(50),
  CONSTRAINT PK_AGENCE PRIMARY KEY (ID)
);

CREATE TABLE APP.CLIENT (
  ID NUMBER NOT NULL,
  AGENCE_ID NUMBER NOT NULL,
  NOM VARCHAR2(50) NOT NULL,
  CONSTRAINT PK_CLIENT PRIMARY KEY (ID),
  CONSTRAINT FK_CLIENT_AGENCE FOREIGN KEY (AGENCE_ID) REFERENCES APP.AGENCE (ID)
);

CREATE INDEX IDX_CLIENT_NOM ON APP.CLIENT (NOM);

CREATE VIEW APP.VW_CLIENT_AGENCE AS
SELECT C.ID, C.NOM, A.NOM AS AGENCE
FROM APP.CLIENT C JOIN APP.AGENCE A ON A.ID = C.AGENCE_ID;
